// ============================================
// MAIN APP COMPONENT
// ============================================
function App() {
  // ============================================
  // CORE STATE MANAGEMENT
  // These states control the application flow
  // ============================================
  const [currentStep, setCurrentStep] = useState(0); // Tracks registration progress (0-4)
  const [completedSteps, setCompletedSteps] = useState(new Set()); // Set of completed steps
  const [formData, setFormData] = useState({}); // User input data
  const [isLoading, setIsLoading] = useState(false); // Loading indicator
  const [responseMessage, setResponseMessage] = useState(''); // API response messages
  const [isSuccess, setIsSuccess] = useState(false); // Success status
  const [errorDetails, setErrorDetails] = useState(''); // Error details
  const [isLoggedIn, setIsLoggedIn] = useState(false); // User authentication status
  const [currentUser, setCurrentUser] = useState(null); // Current user object
  const [notifications, setNotifications] = useState([]); // Notification messages
  const [phoneNumber, setPhoneNumber] = useState(''); // User phone number
  const [serverStatus, setServerStatus] = useState('checking'); // Server connection status
  const [activationDone, setActivationDone] = useState(false); // Service activation status
  const [myPhone, setMyPhone] = useState('0712345678'); // Default phone for demo
  const [isFirstTimeUser, setIsFirstTimeUser] = useState(true); // First time user flag
  const [showWelcomeBack, setShowWelcomeBack] = useState(false); // Welcome back screen flag
  const [registrationError, setRegistrationError] = useState(''); // Registration errors
  const [userExistsError, setUserExistsError] = useState(false); // User exists flag
  const [showMainMenu, setShowMainMenu] = useState(false); // Main menu visibility
  const [registrationComplete, setRegistrationComplete] = useState(false); // Registration complete flag
  const [activationKeyword, setActivationKeyword] = useState(''); // Activation keyword input
  const [isEditingProfile, setIsEditingProfile] = useState(false); // Profile editing mode
  const [showSystemResponse, setShowSystemResponse] = useState(false); // System response visibility
  const [systemResponseMessage, setSystemResponseMessage] = useState(''); // System response message
  const [showSuccessScreen, setShowSuccessScreen] = useState(false); // Success screen visibility
  const [successMessage, setSuccessMessage] = useState(''); // Success message
  const [successTitle, setSuccessTitle] = useState(''); // Success title
  const [isCompleteProfileStep, setIsCompleteProfileStep] = useState(false); // Profile step flag
  const [showLogoutModal, setShowLogoutModal] = useState(false); // Logout modal visibility

  // ===== MATCHING STATE =====
  const [matchSearchActive, setMatchSearchActive] = useState(false); // Search active flag
  const [matchResults, setMatchResults] = useState([]); // Match results array
  const [matchOffset, setMatchOffset] = useState(0); // Pagination offset
  const [totalMatches, setTotalMatches] = useState(0); // Total matches count
  const [selectedMatchDetails, setSelectedMatchDetails] = useState(null); // Selected match details
  const [showMatchDescription, setShowMatchDescription] = useState(false); // Description visibility
  const [consentRequest, setConsentRequest] = useState(null); // Consent request data

  // ============================================
  // DASHBOARD STATE
  // ============================================
  const [allMatches, setAllMatches] = useState([]); // All matches array
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0); // Current match index
  const [incomingRequests, setIncomingRequests] = useState([]); // Incoming requests
  const [currentRequestIndex, setCurrentRequestIndex] = useState(0); // Request pagination index
  const [myMatches, setMyMatches] = useState([]); // Accepted matches
  const [currentMatchListIndex, setCurrentMatchListIndex] = useState(0); // Match list pagination
  const [activeTab, setActiveTab] = useState('discover'); // Current tab (discover, matches, requests, chat)
  const [showProfile, setShowProfile] = useState(false); // Profile modal visibility
  const [showMatchDetails, setShowMatchDetails] = useState(false); // Match details modal
  const [selectedMatch, setSelectedMatch] = useState(null); // Selected match object
  const [isSendingMessage, setIsSendingMessage] = useState(false); // Message sending status
  const [searchCriteria, setSearchCriteria] = useState({ 
    ageRange: '', town: '', county: '' 
  }); // Search criteria
  const [isSearching, setIsSearching] = useState(false); // Search status
  const [hasMoreMatches, setHasMoreMatches] = useState(false); // More matches available flag
  const [editProfileData, setEditProfileData] = useState({}); // Profile edit data
  const [showDescriptionModal, setShowDescriptionModal] = useState(false); // Description modal visibility
  const [descriptionData, setDescriptionData] = useState(null); // Description data

  // ============================================
  // CHAT STATE
  // ============================================
  const [chatContacts, setChatContacts] = useState([]); // Chat contacts
  const [chatMessages, setChatMessages] = useState({}); // Chat messages by contact
  const [newMessage, setNewMessage] = useState(''); // New message input
  const [selectedChatContact, setSelectedChatContact] = useState(null); // Selected chat contact

  // ============================================
  // STATS
  // ============================================
  const [stats, setStats] = useState({
    totalMatches: 0,
    pendingRequests: 0,
    acceptedMatches: 0,
    unreadMessages: 0
  }); // Dashboard statistics

  // ============================================
  // SMS SYSTEM MESSAGES - Full Flow
  // ============================================
  const SYSTEM_MESSAGES = {
    activation: `Welcome to our dating service with 6000 potential dating partners!\n\nTo register SMS start#name#age#gender#county#town to 22141.\nE.g., start#John Doe#26#Male#Nakuru#Naivasha`,

    registrationSuccess: (name) => `Your profile has been created successfully ${name}.\n\nSMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.\nE.g. details#diploma#driver#single#christian#mijikenda`,

    detailsNotProvided: `You were registered for dating with your initial details.\n\nTo search for a MPENZI, SMS match#age#town to 22141\nE.g., match#23-25#Nairobi`,

    detailsProvided: `This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.\nE.g., MYSELF chocolate, lovely, sexy etc.`,

    selfDescriptionSuccess: `You are now registered for dating. To search for a MPENZI, SMS match#age#town to 22141 and meet the person of your dreams.\nE.g., match#23-25#Kisumu`,

    matchFound: (count, gender) => `We have ${count} ${gender} who match your choice! We will send you details of 3 of them shortly. To get more details about a ${gender.slice(0, -1)}, SMS her number e.g., 0722010203 to 22141`,

    matchList: (matches) => {
      return matches.map(m => `${m.name} aged ${m.age}, ${m.phone}`).join('\n') + 
             '\n\nSend NEXT to 22141 to receive details of the remaining ladies';
    },

    nextMatches: (matches) => {
      return matches.map(m => `${m.name} aged ${m.age}, ${m.phone}`).join('\n') + 
             '\n\nSend NEXT to 22141 to receive details of the remaining ladies';
    },

    userDetails: (user) => `${user.name} aged ${user.age}, ${user.county || 'N/A'} County, ${user.town || 'N/A'} town,\n${user.education || 'N/A'}, ${user.profession || 'N/A'}, ${user.marital_status || 'N/A'}, ${user.religion || 'N/A'}, ${user.ethnicity || 'N/A'}.\n\nSend DESCRIBE ${user.phone} to get more details about ${user.name}.`,

    interestNotification: (fromUser, toUser) => `Hi ${toUser.name}, a ${fromUser.gender || 'man'} called ${fromUser.name} is interested in you and requested your details.\nHe is aged ${fromUser.age} based in ${fromUser.town || 'N/A'}.\n\nDo you want to know more about him? Send YES to 22141`,

    userDescription: (user) => `${user.name} describes themselves as ${user.description || 'Not provided'}`,

    consentConfirmation: (fromUser) => `${fromUser.name} aged ${fromUser.age}, ${fromUser.county || 'N/A'} County, ${fromUser.town || 'N/A'} town,\n${fromUser.education || 'N/A'}, ${fromUser.profession || 'N/A'}, ${fromUser.marital_status || 'N/A'}, ${fromUser.religion || 'N/A'}, ${fromUser.ethnicity || 'N/A'}.\n\nSend DESCRIBE ${fromUser.phone} to get more details about ${fromUser.name}.`,

    interestSent: (name) => `Your interest request has been sent successfully to ${name}.\n\nThe other member will be notified.`,

    requestAccepted: (name) => `Congratulations! You have accepted ${name}'s request.\n\nYou may now begin chatting.`
  };

  // ============================================
  // SAMPLE DATA - Gender Based (No Compatibility)
  // ============================================
  // Female sample matches
  const SAMPLE_MATCHES = [
    { id: 1, phone: '0722010203', name: 'Lina Moraa', age: 29, town: 'Nairobi', county: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Kind-hearted and adventurous. Loves hiking and reading.', gender: 'Female' },
    { id: 2, phone: '0701223344', name: 'Dorine Gakii', age: 26, town: 'Nakuru', county: 'Nakuru', profession: 'Teacher', education: 'Diploma', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Caring and dedicated. Loves children and education.', gender: 'Female' },
    { id: 3, phone: '0700112233', name: 'Aisha Bahati', age: 27, town: 'Mombasa', county: 'Mombasa', profession: 'Accountant', education: 'Graduate', religion: 'Muslim', ethnicity: 'Swahili', marital_status: 'single', description: 'Ambitious and hardworking. I love numbers.', gender: 'Female' },
    { id: 4, phone: '0722040506', name: 'Pamela Nafula', age: 26, town: 'Kisumu', county: 'Kisumu', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Tech enthusiast. Loves innovation and building solutions.', gender: 'Female' },
    { id: 5, phone: '0702556677', name: 'Maria Mwende', age: 28, town: 'Kasarani', county: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Diligent, loving, dedicated and will make you tick.', gender: 'Female' },
    { id: 6, phone: '0708990011', name: 'Keziah Cheptab', age: 28, town: 'Eldoret', county: 'Uasin Gishu', profession: 'Doctor', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', description: 'Passionate about healthcare and community service.', gender: 'Female' }
  ];

  // Male sample matches
  const SAMPLE_MALE_MATCHES = [
    { id: 7, phone: '0711000001', name: 'John Mwangi', age: 30, town: 'Nairobi', county: 'Nairobi', profession: 'Engineer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Hardworking and ambitious. Love building things.', gender: 'Male' },
    { id: 8, phone: '0711000002', name: 'David Ochieng', age: 32, town: 'Kisumu', county: 'Kisumu', profession: 'Lawyer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Passionate about justice and community service.', gender: 'Male' },
    { id: 9, phone: '0711000003', name: 'Peter Kiprop', age: 28, town: 'Eldoret', county: 'Uasin Gishu', profession: 'Businessman', education: 'Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', description: 'Entrepreneurial spirit. Love meeting new people.', gender: 'Male' },
    { id: 10, phone: '0711000004', name: 'Samuel Mwangi', age: 27, town: 'Nakuru', county: 'Nakuru', profession: 'Developer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Tech enthusiast and code lover.', gender: 'Male' },
    { id: 11, phone: '0711000005', name: 'James Kamau', age: 31, town: 'Thika', county: 'Kiambu', profession: 'Architect', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Creative designer. Love art and architecture.', gender: 'Male' },
    { id: 12, phone: '0711000006', name: 'Michael Omondi', age: 29, town: 'Mombasa', county: 'Mombasa', profession: 'Pilot', education: 'Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Adventurous and love exploring new places.', gender: 'Male' }
  ];

  // Sample incoming requests
  const SAMPLE_REQUESTS = [
    { id: 101, phone: '0723000001', name: 'Michael Ochieng', age: 30, town: 'Nairobi', county: 'Nairobi', profession: 'Lawyer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending', date: '2024-01-15', gender: 'Male' },
    { id: 102, phone: '0723000002', name: 'David Kiprop', age: 28, town: 'Eldoret', county: 'Uasin Gishu', profession: 'Businessman', education: 'Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending', date: '2024-01-14', gender: 'Male' },
    { id: 103, phone: '0723000003', name: 'Samuel Mwangi', age: 32, town: 'Nakuru', county: 'Nakuru', profession: 'Developer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending', date: '2024-01-13', gender: 'Male' }
  ];

  // Sample accepted matches
  const SAMPLE_MY_MATCHES = [
    { id: 201, phone: '0724000001', name: 'Grace Akinyi', age: 27, town: 'Kisumu', county: 'Kisumu', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', status: 'accepted', gender: 'Female' },
    { id: 202, phone: '0724000002', name: 'Peter Mwangi', age: 29, town: 'Nakuru', county: 'Nakuru', profession: 'Engineer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', status: 'accepted', gender: 'Male' },
    { id: 203, phone: '0724000003', name: 'Sarah Wanjiru', age: 25, town: 'Thika', county: 'Kiambu', profession: 'Designer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', status: 'accepted', gender: 'Female' }
  ];

  // ============================================
  // API CALL FUNCTIONS
  // These functions communicate with the backend server
  // ============================================
  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = {
        method: method,
        headers: { 'Content-Type': 'application/json' }
      };
      if (body) {
        options.body = JSON.stringify(body);
      }
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      const data = await response.json();
      console.log(`API ${method} ${endpoint}:`, data);
      return data;
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ============================================
  // LOAD SAVED STATE FROM LOCALSTORAGE
  // This ensures user data persists across page refreshes
  // ============================================
  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);

        if (parsed.currentUser && parsed.isLoggedIn) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
          setAllMatches(parsed.allMatches || []);
          setIncomingRequests(parsed.incomingRequests || []);
          setMyMatches(parsed.myMatches || []);
          setChatContacts(parsed.chatContacts || []);
          setChatMessages(parsed.chatMessages || {});
          setActiveTab(parsed.activeTab || 'discover');
          setMyPhone(parsed.myPhone || '0712345678');
          setActivationDone(true);
          setShowWelcomeBack(true);
          setShowMainMenu(true);
          setMatchOffset(parsed.matchOffset || 0);
          setTotalMatches(parsed.totalMatches || 0);

          setTimeout(() => {
            addNotification(`👋 Welcome back, ${parsed.currentUser.name}!`);
          }, 500);

          setIsFirstTimeUser(false);
        } else {
          setCurrentStep(parsed.currentStep || 0);
          setCompletedSteps(new Set(parsed.completedSteps || []));
          setPhoneNumber(parsed.phoneNumber || '');
          setActivationDone(parsed.activationDone || false);
          setMyPhone(parsed.myPhone || '0712345678');
          if (parsed.currentUser) {
            setCurrentUser(parsed.currentUser);
          }
          setIsFirstTimeUser(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
      setIsFirstTimeUser(true);
    }
  }, []);

  // ============================================
  // SAVE STATE TO LOCALSTORAGE
  // Automatically saves whenever relevant state changes
  // ============================================
  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        currentUser,
        isLoggedIn,
        phoneNumber,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatContacts,
        chatMessages,
        activeTab,
        myPhone,
        showMainMenu,
        searchCriteria,
        matchOffset,
        totalMatches
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, currentUser, isLoggedIn, phoneNumber, activationDone, allMatches, incomingRequests, myMatches, chatContacts, chatMessages, activeTab, myPhone, showMainMenu, searchCriteria, matchOffset, totalMatches]);

  // ============================================
  // UPDATE STATS
  // Automatically recalculates dashboard statistics
  // ============================================
  useEffect(() => {
    setStats({
      totalMatches: allMatches.length + myMatches.length,
      pendingRequests: incomingRequests.filter(r => r.status === 'pending').length,
      acceptedMatches: myMatches.length,
      unreadMessages: chatContacts.reduce((sum, c) => sum + (c.unread || 0), 0)
    });
  }, [allMatches, incomingRequests, myMatches, chatContacts]);

  // ============================================
  // CHECK SERVER CONNECTION
  // Verifies backend server is running
  // ============================================
  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // HELPER FUNCTIONS
  // ============================================

  // Update form data when user inputs change
  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  // Add a notification that auto-dismisses after 5 seconds
  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  // Calculate registration progress percentage
  const getProgress = () => {
    if (!activationDone) return 0;
    return Math.round((completedSteps.size / 4) * 100);
  };

  // Show success screen with title and message
  const showSuccess = (title, message) => {
    setSuccessTitle(title);
    setSuccessMessage(message);
    setShowSuccessScreen(true);
  };

  // ============================================
  // GENDER HELPER FUNCTIONS
  // ============================================

  // Get opposite gender for matching
  const getOppositeGender = (gender) => {
    if (!gender) return null;
    return gender.toLowerCase() === 'male' ? 'Female' : 'Male';
  };

  // Filter matches by opposite gender only
  const filterMatchesByGender = (matches, userGender) => {
    if (!userGender || !matches || matches.length === 0) return matches;
    const oppositeGender = getOppositeGender(userGender);
    return matches.filter(m => m.gender && m.gender.toLowerCase() === oppositeGender.toLowerCase());
  };

  // ============================================
  // EDIT PROFILE FUNCTIONS
  // ============================================

  // Start editing profile - populate form with current data
  const startEditProfile = () => {
    setEditProfileData({
      name: currentUser?.name || '',
      age: currentUser?.age || '',
      gender: currentUser?.gender || '',
      county: currentUser?.county || '',
      town: currentUser?.town || '',
