    switch(statType) {
      case 'totalMatches':
        setActiveTab('discover');
        addNotification('👥 Showing all matches');
        break;
      case 'pendingRequests':
        setActiveTab('requests');
        if (incomingRequests.length === 0) {
          setIncomingRequests(SAMPLE_REQUESTS);
        }
        addNotification('📬 Showing pending requests');
        break;
      case 'acceptedMatches':
        setActiveTab('matches');
        if (myMatches.length === 0) {
          setMyMatches(SAMPLE_MY_MATCHES);
        }
        addNotification('💕 Showing accepted matches');
        break;
      case 'unreadMessages':
        setActiveTab('chat');
        addNotification('💬 Showing unread messages');
        break;
      default:
        break;
    }
  };

  // ============================================
  // RENDER MAIN MENU
  // ============================================
  const renderMainMenu = () => {
    const hasProfile = completedSteps.has(1);
    const hasDescription = completedSteps.has(2);

    return (
      <div className="main-menu-container">
        <div className="main-menu-header">
          <h1>💑 PENZI Dating</h1>
          <p className="menu-subtitle">Welcome back. Choose one of the options below.</p>
          {currentUser && (
            <div className="menu-user-info">
              <span>👋 Welcome, {currentUser.name || 'User'}!</span>
            </div>
          )}
        </div>

        <div className="dashboard-stats">
          <div className="stat-card matches clickable" onClick={() => handleStatClick('totalMatches')}>
            <span className="stat-icon">👥</span>
            <div className="stat-number">{stats.totalMatches}</div>
            <div className="stat-label">Total Matches</div>
          </div>
          <div className="stat-card requests clickable" onClick={() => handleStatClick('pendingRequests')}>
            <span className="stat-icon">📬</span>
            <div className="stat-number">{stats.pendingRequests}</div>
            <div className="stat-label">Pending Requests</div>
          </div>
          <div className="stat-card accepted clickable" onClick={() => handleStatClick('acceptedMatches')}>
            <span className="stat-icon">💕</span>
            <div className="stat-number">{stats.acceptedMatches}</div>
            <div className="stat-label">Accepted Matches</div>
          </div>
          <div className="stat-card messages clickable" onClick={() => handleStatClick('unreadMessages')}>
            <span className="stat-icon">💬</span>
            <div className="stat-number">{stats.unreadMessages}</div>
            <div className="stat-label">Unread Messages</div>
          </div>
        </div>

        <div className="main-menu-options">
          <div className="menu-card profile-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            setShowProfile(true);
            setIsEditingProfile(false);
          }}>
            <div className="menu-card-icon">👤</div>
            <div className="menu-card-content">
              <h3>My Profile</h3>
              <p>View and edit your profile</p>
              {hasProfile && hasDescription && <span className="menu-card-badge">✅ Complete</span>}
              {(!hasProfile || !hasDescription) && <span className="menu-card-badge inactive">⏳ Incomplete</span>}
            </div>
          </div>

          <div className="menu-card matches-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            if (allMatches.length === 0) {
              const userGender = currentUser?.gender;
              let sampleData = [];

              if (userGender && userGender.toLowerCase() === 'male') {
                sampleData = SAMPLE_MATCHES;
              } else if (userGender && userGender.toLowerCase() === 'female') {
                sampleData = SAMPLE_MALE_MATCHES;
              } else {
                sampleData = [...SAMPLE_MATCHES, ...SAMPLE_MALE_MATCHES];
              }

              setAllMatches(sampleData.slice(0, 3));
              setMatchResults(sampleData);
              setHasMoreMatches(sampleData.length > 3);
              setMatchSearchActive(true);
              addNotification(`✅ Found ${sampleData.length} matches!`);
            }
          }}>
            <div className="menu-card-icon">❤️</div>
            <div className="menu-card-content">
              <h3>Search Matches</h3>
              <p>Find your perfect partner</p>
              <span className="menu-card-sub">Search by: Age • Town</span>
            </div>
          </div>

          <div className="menu-card requests-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('requests');
            if (incomingRequests.length === 0) {
              setIncomingRequests(SAMPLE_REQUESTS);
            }
          }}>
            <div className="menu-card-icon">💌</div>
            <div className="menu-card-content">
              <h3>My Requests</h3>
              <p>People interested in you</p>
              {stats.pendingRequests > 0 && <span className="menu-card-badge">{stats.pendingRequests} new</span>}
            </div>
          </div>

          <div className="menu-card chat-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('chat');
          }}>
            <div className="menu-card-icon">💬</div>
            <div className="menu-card-content">
              <h3>Chats</h3>
              <p>Your conversations</p>
              {stats.unreadMessages > 0 && <span className="menu-card-badge">{stats.unreadMessages} unread</span>}
            </div>
          </div>

          <div className="menu-card logout-card" onClick={() => setShowLogoutModal(true)}>
            <div className="menu-card-icon">🚪</div>
            <div className="menu-card-content">
              <h3>Logout</h3>
              <p>Exit the application</p>
            </div>
          </div>
        </div>

        <div className="main-menu-footer">
          <span className="menu-version">v2.0 • PENZI Dating Service</span>
          <span className="menu-version">🔒 Secure • Private</span>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER DASHBOARD
  // ============================================
  const renderDashboard = () => {
    const hasRequests = incomingRequests.length > 0;
    const hasChatContacts = chatContacts.length > 0;

    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="header-left">
            <button className="btn-home" onClick={goHome} title="Home">🏠</button>
            <h1>💑 PENZI</h1>
            <span className="live-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="btn-menu" onClick={() => setShowMainMenu(true)} title="Main Menu">📋</button>
            <button className="profile-btn" onClick={() => { setShowProfile(true); setIsEditingProfile(false); }} title="My Profile">👤</button>
            <button className="btn-exit" onClick={() => setShowLogoutModal(true)} title="Logout">🚪</button>
          </div>
        </header>

        <div className="dashboard-stats">
          <div className="stat-card matches clickable" onClick={() => handleStatClick('totalMatches')}>
            <span className="stat-icon">👥</span>
            <div className="stat-number">{stats.totalMatches}</div>
            <div className="stat-label">Total Matches</div>
          </div>
          <div className="stat-card requests clickable" onClick={() => handleStatClick('pendingRequests')}>
            <span className="stat-icon">📬</span>
            <div className="stat-number">{stats.pendingRequests}</div>
            <div className="stat-label">Pending Requests</div>
          </div>
          <div className="stat-card accepted clickable" onClick={() => handleStatClick('acceptedMatches')}>
            <span className="stat-icon">💕</span>
            <div className="stat-number">{stats.acceptedMatches}</div>
            <div className="stat-label">Accepted Matches</div>
          </div>
          <div className="stat-card messages clickable" onClick={() => handleStatClick('unreadMessages')}>
            <span className="stat-icon">💬</span>
            <div className="stat-number">{stats.unreadMessages}</div>
            <div className="stat-label">Unread Messages</div>
          </div>
        </div>

        <nav className="dashboard-nav">
          <button 
            className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('discover');
              if (allMatches.length === 0) {
                const userGender = currentUser?.gender;
                let sampleData = [];

                if (userGender && userGender.toLowerCase() === 'male') {
                  sampleData = SAMPLE_MATCHES;
                } else if (userGender && userGender.toLowerCase() === 'female') {
                  sampleData = SAMPLE_MALE_MATCHES;
                } else {
                  sampleData = [...SAMPLE_MATCHES, ...SAMPLE_MALE_MATCHES];
                }

                setAllMatches(sampleData.slice(0, 3));
                setMatchResults(sampleData);
                setHasMoreMatches(sampleData.length > 3);
                setMatchSearchActive(true);
              }
            }}
          >
            🔍 Discover
            <span className="nav-badge">{allMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('matches');
              if (myMatches.length === 0) {
                setMyMatches(SAMPLE_MY_MATCHES);
              }
            }}
          >
            💕 Matches
            <span className="nav-badge">{myMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('requests');
              if (incomingRequests.length === 0) {
                setIncomingRequests(SAMPLE_REQUESTS);
              }
            }}
          >
            📬 Requests
            {hasRequests && <span className="nav-badge red">{incomingRequests.length}</span>}
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('chat');
            }}
          >
            💬 Chat
            {hasChatContacts && <span className="nav-badge">{chatContacts.length}</span>}
          </button>
        </nav>

        <main className="dashboard-content">
          {activeTab === 'discover' && renderDiscoverTable()}
          {activeTab === 'matches' && renderMyMatchesTable()}
          {activeTab === 'requests' && renderRequestsTable()}
          {activeTab === 'chat' && (
            <div className="chat-container-whatsapp">
              {renderChat()}
            </div>
          )}
        </main>

        {showMatchDetails && renderProfileModal()}
        {showProfile && renderProfileDetails()}
        {renderDescriptionModal()}
      </div>
    );
  };

  // ============================================
  // RENDER DESCRIPTION MODAL
  // ============================================
  const renderDescriptionModal = () => {
    if (!showDescriptionModal || !descriptionData) return null;

    return (
      <div className="modal-overlay" onClick={() => { setShowDescriptionModal(false); setDescriptionData(null); }}>
        <div className="modal-content description-modal" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => { setShowDescriptionModal(false); setDescriptionData(null); }}>✕</button>
          <div className="description-modal-content">
            <div className="description-avatar">{descriptionData.name?.charAt(0) || '?'}</div>
            <h2>{descriptionData.name}</h2>
            <p className="description-age">{descriptionData.age} years • {descriptionData.town}</p>
            <div className="description-text">
              <span className="description-label">💭 About Me</span>
              <p>{descriptionData.description || 'No description provided yet.'}</p>
            </div>
            <div className="modal-actions">
              <button className="btn-secondary" onClick={() => { setShowDescriptionModal(false); setDescriptionData(null); }}>
                Close
              </button>
              <button className="btn-primary" onClick={() => {
                setShowDescriptionModal(false);
                handleExpressInterest(descriptionData.phone);
              }}>
                💕 Express Interest
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER LOGOUT MODAL
  // ============================================
  const renderLogoutModal = () => {
    if (!showLogoutModal) return null;

    return (
      <div className="modal-overlay logout-modal-overlay" onClick={() => setShowLogoutModal(false)}>
        <div className="modal-content logout-modal" onClick={(e) => e.stopPropagation()}>
          <div className="logout-modal-icon">🚪</div>
          <h2 className="logout-modal-title">Exit PENZI Dating Service</h2>
          <p className="logout-modal-message">Are you sure you want to exit? You'll need to log in again to access your matches and messages.</p>
          <div className="logout-modal-actions">
            <button className="logout-modal-btn cancel" onClick={() => setShowLogoutModal(false)}>
              ✖ Cancel
            </button>
            <button className="logout-modal-btn confirm" onClick={handleLogout}>
              ✔ Yes, Logout
            </button>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // BUILD SMS PREVIEW (for display purposes)
  // ============================================
  const buildSmsPreview = (step) => {
    if (step === 2) {
      return `start#${formData.name || 'Jamal Jalang\'o'}#${formData.age || '29'}#${formData.gender || 'Male'}#${formData.county || 'Mombasa'}#${formData.town || 'Bamburi'}`;
    }
    if (step === 3) {
      return `details#${formData.education_level || 'graduate'}#${formData.profession || 'accountant'}#${formData.marital_status || 'divorced'}#${formData.religion || 'muslim'}#${formData.ethnicity || 'somali'}`;
    }
    if (step === 4) {
      return `MYSELF ${formData.description || 'tall, dark and handsome'}`;
    }
    if (step === 5) {
      return `match#${formData.ageRange || '26-30'}#${formData.town || 'Nairobi'}`;
    }
    return '';
  };

  // ============================================
  // MAIN RETURN - Renders the appropriate screen
  // ============================================
  return (
    <div className="app">
      {renderNotifications()}
      {renderLogoutModal()}

      {showSuccessScreen ? (
        renderSuccessScreen()
      ) : userExistsError ? (
        renderUserExistsWarning()
      ) : showWelcomeBack && !isLoggedIn ? (
        renderWelcomeBack()
      ) : isLoggedIn ? (
        showMainMenu ? renderMainMenu() : renderDashboard()
      ) : (
        activationDone ? (
          isCompleteProfileStep ? (
            renderCompleteProfile()
          ) : (
            renderRegistrationStep()
          )
        ) : (
          renderActivationPage()
        )
      )}
    </div>
  );
}

export default App;
